#include <fstream>
#include <algorithm>
using namespace std;
ifstream fin("macarie.in");
ofstream fout("macarie.out");
const int VMAX = 1000000;
int f[VMAX + 1];
long long p[VMAX + 1];
int main() {
    int n, q;
    fin >> n >> q;
    for (int i = 0; i < n; i++) {
        int x;
        fin >> x;
        f[x]++;
    }
    // p[d] = câți termeni din D sunt <= d
    for (int d = 1; d <= VMAX; d++) {
        long long c = 0;
        for (int m = d; m <= VMAX; m += d) c += f[m];
        p[d] = p[d - 1] + c;
    }
    for (int i = 0; i < q; i++) {
        long long poz;
        fin >> poz;
        fout << lower_bound(p + 1, p + VMAX + 1, poz) - p << " ";
    }
    return 0;
}

