int v[100000];
int sc(int x) {
    int s = 0;
    while (x) {
        s += x % 10;
        x /= 10;
    }
    return s;
}
bool cmp(int a, int b) {
    int sa = sc(a), sb = sc(b);
    if (sa != sb) return sa < sb;
    return a < b;
}
