#include <iostream>
#include <algorithm>
using namespace std;
pair<long long, long long> p[100000];
bool cmp(const pair<long long, long long>& a, const pair<long long, long long>& b) {
    long long da = a.first * a.first + a.second * a.second;
    long long db = b.first * b.first + b.second * b.second;
    if (da != db) return da < db;
    return a < b;
}
int main() {
    int n;
    cin >> n;
    for (int i = 0; i < n; i++) cin >> p[i].first >> p[i].second;
    sort(p, p + n, cmp);
    for (int i = 0; i < n; i++) cout << p[i].first << " " << p[i].second << "\n";
    return 0;
}

#include <iostream>
#include <algorithm>
using namespace std;
long long x[100000];
int n, c;
bool incap(long long d) {
    int cnt = 1;
    long long ult = x[0];
    for (int i = 1; i < n; i++)
        if (x[i] - ult >= d) {
            cnt++;
            ult = x[i];
        }
    return cnt >= c;
}
int main() {
    cin >> n >> c;
    for (int i = 0; i < n; i++) cin >> x[i];
    sort(x, x + n);
    long long st = 1, dr = x[n - 1] - x[0], r = 0;
    while (st <= dr) {
        long long mij = (st + dr) / 2;
        if (incap(mij)) {
            r = mij;
            st = mij + 1;
        } else dr = mij - 1;
    }
    cout << r;
    return 0;
}

