#include <iostream>
using namespace std;
int f[1000001];
int main() {
    ios::sync_with_stdio(false);
    cin.tie(0);
    int n, k, x;
    long long c = 0;
    cin >> n >> k;
    for (int i = 0; i < n; i++) {
        cin >> x;
        int y = k - x;
        if (y >= 0 && y <= 1000000) c += f[y];
        f[x]++;
    }
    cout << c;
