#include <iostream>
using namespace std;
int c[10];
int main() {
    int n;
    long long x;
    bool gasit = false;
    cin >> n;
    for (int i = 0; i < n; i++) {
        cin >> x;
        bool are[10] = {false};
        do {
            are[x % 10] = true;
            x /= 10;
        } while (x > 0);
        for (int d = 0; d < 10; d++)
            if (are[d]) c[d]++;
    }
    for (int d = 0; d < 10; d++)
        if (c[d] == n) {
            cout << d << " ";
            gasit = true;
        }
    if (!gasit) cout << -1;
    return 0;
}

