#include <iostream>
using namespace std;
long long f[91];
int main() {
    int n;
    long long x;
    cin >> n;
    for (int i = 0; i < n; i++) {
        cin >> x;
        int s = 0;
        while (x > 0) {
            s += x % 10;
            x /= 10;
        }
        f[s]++;
    }
    long long c = 0;
    for (int s = 0; s <= 90; s++) c += f[s] * (f[s] - 1) / 2;
    cout << c;
    return 0;
}

