#include <iostream>
using namespace std;
int main() {
    long long n;
    int k = 0;
    cin >> n;
    while (n != 1 && n != 4) {
        long long s = 0;
        while (n > 0) {
            s = s + (n % 10) * (n % 10);
            n = n / 10;
        }
        n = s;
        k = k + 1;
    }
    if (n == 1) cout << "DA " << k;
    else cout << "NU " << k;
    return 0;
}

